Lemma amemset_rip : forall (sp d n : Z) (ra gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : mem) (lo : Z),
  stk asegs m lo (sp + -2128) -> lo <= sp - AMEMSET_DEPTH -> kHighShadowEnd + 8 <= lo -> sp < 2^63 ->
  0 <= d -> 0 < n -> d + n < 2^63 ->
  acc asegs m d n -> rng_ok d n -> m2s_cells m -> mem_inv asegs m ->
  evt asegs (fun ms' => exists (m' : mem) (ra' t0' t1' t2' s1' a3' a4' a5' a6' a7' s2' s3' s5' t3' t4' t5' t6' : word),
      ms' = MS (mkR ra' (Z_to_bv 64 (sp + -2128)) gp tp t0' t1' t2' s0 s1' (Z_to_bv 64 d) a1 (Z_to_bv 64 n) a3' a4' a5' a6' a7'
                    s2' s3' s4 s5' s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
               F (Z_to_bv 64 0xc9e08) fc None m' (seg_rom asegs)
      /\ munch [(sp - 2208, sp - 2128)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (sp + -2128))
    (MS (mkR ra (Z_to_bv 64 (sp + -2128)) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 d) a1 (Z_to_bv 64 n) a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xc9f4c) fc None m (seg_rom asegs)).
